/** Regression tests for explicit statements that are also inferred (GH-6276). */
class SchemaCachingRDFSInferencerExplicitStatementsTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NAMESPACE = "urn:inferencer-explicit:";
	private static final IRI SCHEMA_GRAPH = VF.createIRI(NAMESPACE, "schema");
	private static final IRI DATA_GRAPH = VF.createIRI(NAMESPACE, "data");
	private static final IRI OTHER_GRAPH = VF.createIRI(NAMESPACE, "other");
	private static final IRI HAS_PART = VF.createIRI(NAMESPACE, "hasPart");
	private static final IRI WHOLE = VF.createIRI(NAMESPACE, "Whole");
	private static final IRI PART = VF.createIRI(NAMESPACE, "Part");
	private static final IRI WHOLE_INSTANCE = VF.createIRI(NAMESPACE, "whole-instance");
	private static final IRI PART_INSTANCE = VF.createIRI(NAMESPACE, "part-instance");
	private static final IRI OTHER_WHOLE = VF.createIRI(NAMESPACE, "other-whole");
	private static final IRI OTHER_PART = VF.createIRI(NAMESPACE, "other-part");

	@TempDir
	Path dataDirectory;

	@ParameterizedTest(name = "{0}, data={1}, inferredToDefault={2}")
	@MethodSource("configurations")
	void clearingGraphRemovesUnsupportedInferences(Store store, Resource dataGraph, boolean inferredToDefault) {
		SailRepository repository = createRepository(store, inferredToDefault);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				addExplicitData(connection, dataGraph);
				connection.begin();
				connection.add(OTHER_WHOLE, HAS_PART, OTHER_PART, OTHER_GRAPH);
				connection.commit();

				connection.begin();
				connection.clear(dataGraph);
				connection.commit();
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertFalse(connection.hasStatement(WHOLE_INSTANCE, null, null, true),
						"clearing the graph must remove explicit and unsupported inferred subject statements");
				assertFalse(connection.hasStatement(PART_INSTANCE, null, null, true),
						"clearing the graph must remove explicit and unsupported inferred object types");
				assertTrue(connection.hasStatement(OTHER_WHOLE, HAS_PART, OTHER_PART, false, OTHER_GRAPH),
						"clearing one graph must preserve the other graph's explicit premise");
				Resource otherInferenceGraph = inferredToDefault ? null : OTHER_GRAPH;
				assertTrue(connection.hasStatement(OTHER_WHOLE, RDF.TYPE, WHOLE, true, otherInferenceGraph));
				assertTrue(connection.hasStatement(OTHER_PART, RDF.TYPE, PART, true, otherInferenceGraph));
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}, data={1}, inferredToDefault={2}")
	@MethodSource("configurations")
	void removingExplicitTypesPreservesEntailedTypes(Store store, Resource dataGraph, boolean inferredToDefault) {
		SailRepository repository = createRepository(store, inferredToDefault);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				addExplicitData(connection, dataGraph);
				removeExplicitTypes(connection, dataGraph);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertTypesAreNotExplicit(connection, dataGraph);
				assertTrue(connection.hasStatement(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, false, dataGraph));
				assertTypesExist(connection, true, inferredToDefault ? null : dataGraph);
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}, data={1}, inferredToDefault={2}")
	@MethodSource("configurations")
	void removedTypesCanBeMadeExplicitAgain(Store store, Resource dataGraph, boolean inferredToDefault) {
		SailRepository repository = createRepository(store, inferredToDefault);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				addExplicitData(connection, dataGraph);
				removeExplicitTypes(connection, dataGraph);
				assertTypesAreNotExplicit(connection, dataGraph);
				addExplicitTypes(connection, dataGraph);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertTypesExist(connection, false, dataGraph);
				// Repeated explicit additions must be idempotent, including after a fresh connection.
				addExplicitTypes(connection, dataGraph);
				assertTypesExist(connection, false, dataGraph);
				for (int cycle = 0; cycle < 2; cycle++) {
					removeExplicitTypes(connection, dataGraph);
					assertTypesAreNotExplicit(connection, dataGraph);
					addExplicitTypes(connection, dataGraph);
					assertTypesExist(connection, false, dataGraph);
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}, data={1}, inferredToDefault={2}")
	@MethodSource("configurations")
	void inferredTypesCanBeMadeExplicit(Store store, Resource dataGraph, boolean inferredToDefault) {
		SailRepository repository = createRepository(store, inferredToDefault);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				connection.add(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, dataGraph);
				connection.commit();
				assertTypesAreNotExplicit(connection, dataGraph);
				assertTypesExist(connection, true, inferredToDefault ? null : dataGraph);
				addExplicitTypes(connection, dataGraph);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertTypesExist(connection, false, dataGraph);
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}, data={1}, inferredToDefault={2}")
	@MethodSource("configurations")
	void explicitPromotionSurvivesInferenceRebuild(Store store, Resource dataGraph, boolean inferredToDefault) {
		SailRepository repository = createRepository(store, inferredToDefault);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				connection.add(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, dataGraph);
				connection.commit();
				assertTypesAreNotExplicit(connection, dataGraph);
				assertTypesExist(connection, true, inferredToDefault ? null : dataGraph);

				connection.begin();
				connection.add(WHOLE_INSTANCE, RDF.TYPE, WHOLE, dataGraph);
				connection.add(PART_INSTANCE, RDF.TYPE, PART, dataGraph);
				// Removing the premise clears and rebuilds inferred statements in this transaction.
				connection.remove(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, dataGraph);
				connection.commit();
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertTypesExist(connection, false, dataGraph);
				assertFalse(connection.hasStatement(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, true));
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "{0}, data={1}, inferredToDefault={2}")
	@MethodSource("configurations")
	void rolledBackRemovalPreservesExplicitTypes(Store store, Resource dataGraph, boolean inferredToDefault) {
		SailRepository repository = createRepository(store, inferredToDefault);
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				addExplicitData(connection, dataGraph);
				connection.begin();
				connection.remove((Resource) null, RDF.TYPE, null, dataGraph);
				// Reading flushes the removal and re-inference before rollback.
				assertTypesAreNotExplicit(connection, dataGraph);
				connection.rollback();
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				assertTypesExist(connection, false, dataGraph);
				assertTrue(connection.hasStatement(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, false, dataGraph));
			}
		} finally {
			repository.shutDown();
		}
	}

	private SailRepository createRepository(Store store, boolean inferredToDefault) {
		NotifyingSail base = store == Store.NATIVE ? new NativeStore(dataDirectory.toFile()) : new MemoryStore();
		SchemaCachingRDFSInferencer inferencer = new SchemaCachingRDFSInferencer(base);
		inferencer.setAddInferredStatementsToDefaultContext(inferredToDefault);
		SailRepository repository = new SailRepository(inferencer);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			connection.add(HAS_PART, RDFS.DOMAIN, WHOLE, SCHEMA_GRAPH);
			connection.add(HAS_PART, RDFS.RANGE, PART, SCHEMA_GRAPH);
			connection.commit();
		}
		return repository;
	}

	private static void addExplicitData(RepositoryConnection connection, Resource dataGraph) {
		connection.begin();
		connection.add(WHOLE_INSTANCE, RDF.TYPE, WHOLE, dataGraph);
		connection.add(PART_INSTANCE, RDF.TYPE, PART, dataGraph);
		connection.add(WHOLE_INSTANCE, HAS_PART, PART_INSTANCE, dataGraph);
		connection.commit();
	}

	private static void addExplicitTypes(RepositoryConnection connection, Resource dataGraph) {
		connection.begin();
		connection.add(WHOLE_INSTANCE, RDF.TYPE, WHOLE, dataGraph);
		connection.add(PART_INSTANCE, RDF.TYPE, PART, dataGraph);
		connection.commit();
	}

	private static void removeExplicitTypes(RepositoryConnection connection, Resource dataGraph) {
		connection.begin();
		connection.remove((Resource) null, RDF.TYPE, null, dataGraph);
		connection.commit();
	}

	private static void assertTypesAreNotExplicit(RepositoryConnection connection, Resource dataGraph) {
		assertFalse(connection.hasStatement(WHOLE_INSTANCE, RDF.TYPE, WHOLE, false, dataGraph));
		assertFalse(connection.hasStatement(PART_INSTANCE, RDF.TYPE, PART, false, dataGraph));
	}

	private static void assertTypesExist(RepositoryConnection connection, boolean includeInferred, Resource graph) {
		assertTrue(connection.hasStatement(WHOLE_INSTANCE, RDF.TYPE, WHOLE, includeInferred, graph),
				"the domain type must exist with the requested explicit/inferred visibility");
		assertTrue(connection.hasStatement(PART_INSTANCE, RDF.TYPE, PART, includeInferred, graph),
				"the range type must exist with the requested explicit/inferred visibility");
	}

	private static Stream<Arguments> configurations() {
		return Stream.of(Store.values())
				.flatMap(store -> Stream.of(DATA_GRAPH, null)
						.flatMap(graph -> Stream.of(false, true)
								.map(inferredToDefault -> Arguments.of(store, graph, inferredToDefault))));
	}

	private enum Store {
		MEMORY,
		NATIVE
	}
}
